// Entrada do WF4: { destino, latitude, longitude, idioma, dias }
const raw = $input.first().json;
const body = raw.body ?? raw;
const idiomasSuportados = ['pt', 'en', 'es', 'fr', 'zh', 'hi', 'ar', 'ru'];

const latitude = Number(body.latitude);
const longitude = Number(body.longitude);
const codigo = String(body.idioma ?? 'pt').trim().toLowerCase().split(/[-_;,\s]/)[0];
const dias = Math.min(Math.max(parseInt(body.dias ?? body.dias_estadia ?? 3, 10) || 3, 1), 7);

const coordenadasValidas = Number.isFinite(latitude) && Number.isFinite(longitude)
  && Math.abs(latitude) <= 90 && Math.abs(longitude) <= 180
  && !(latitude === 0 && longitude === 0);

return [{
  json: {
    destino: String(body.destino ?? 'Destino').trim().slice(0, 120),
    latitude,
    longitude,
    idioma: idiomasSuportados.includes(codigo) ? codigo : 'pt',
    dias,
    coordenadas_validas: coordenadasValidas,
  },
}];

// Mesmos limiares de backend/app/services/clima_service.py (avaliar_condicoes_climaticas)
const LIMIAR = {
  chuvaForteProb: 70, chuvaForteMm: 10, chuvaProb: 40, chuvaMm: 2,
  calorExtremo: 35, calor: 32, frio: 12,
};
const entrada = $('Normalizar Entrada').first().json;
const daily = $input.first().json.daily ?? {};
const datas = Array.isArray(daily.time) ? daily.time : [];

function avaliarDia(tmax, tmin, mm, prob) {
  const alertas = [];
  let severo = false;
  const p = Number(prob ?? 0);
  const c = Number(mm ?? 0);
  if (p >= LIMIAR.chuvaForteProb || c >= LIMIAR.chuvaForteMm) { alertas.push('chuva_forte'); severo = true; }
  else if (p >= LIMIAR.chuvaProb || c >= LIMIAR.chuvaMm) { alertas.push('chuva'); }
  if (tmax != null && tmax >= LIMIAR.calorExtremo) { alertas.push('calor_extremo'); severo = true; }
  else if (tmax != null && tmax >= LIMIAR.calor) { alertas.push('calor'); }
  if (tmin != null && tmin <= LIMIAR.frio) { alertas.push('frio'); }
  return { nivel: severo ? 'vermelho' : (alertas.length ? 'amarelo' : 'verde'), alertas };
}

const previsao = datas.map((data, i) => {
  const tmax = daily.temperature_2m_max?.[i] ?? null;
  const tmin = daily.temperature_2m_min?.[i] ?? null;
  const mm = daily.precipitation_sum?.[i] ?? null;
  const prob = daily.precipitation_probability_max?.[i] ?? null;
  return { data, temperatura_max_c: tmax, temperatura_min_c: tmin, precipitacao_mm: mm, probabilidade_chuva: prob, ...avaliarDia(tmax, tmin, mm, prob) };
});

const ordem = { verde: 0, amarelo: 1, vermelho: 2 };
const nivel = previsao.length
  ? previsao.reduce((pior, d) => (ordem[d.nivel] > ordem[pior] ? d.nivel : pior), 'verde')
  : 'indisponivel';
const alertas = [...new Set(previsao.flatMap((d) => d.alertas))];

const nomesIdioma = {
  pt: 'português do Brasil', en: 'inglês', es: 'espanhol', fr: 'francês',
  zh: 'mandarim (chinês simplificado)', hi: 'hindi', ar: 'árabe', ru: 'russo',
};
const resumoDias = previsao.map((d) =>
  `${d.data}: máx ${d.temperatura_max_c ?? '?'} °C, mín ${d.temperatura_min_c ?? '?'} °C, ` +
  `chuva ${d.precipitacao_mm ?? 0} mm (${d.probabilidade_chuva ?? 0}%), nível ${d.nivel}`).join('\n');

const prompt = [
  `Você é um assistente de viagem. Destino: ${entrada.destino}.`,
  `Previsão diária (Open-Meteo):\n${resumoDias || 'sem dados de previsão'}`,
  `Nível geral de alerta: ${nivel}. Alertas: ${alertas.join(', ') || 'nenhum'}.`,
  'Escreva de 3 a 5 orientações práticas e curtas (vestuário, horários, hidratação, deslocamento na estrada,',
  'plano B coberto em caso de chuva). Texto puro, uma orientação por linha começando com "• ", sem Markdown.',
  `IDIOMA: escreva tudo em ${nomesIdioma[entrada.idioma]}.`,
  'Mantenha nomes próprios de patrimônios, cidades e rodovias exatamente como no original em português',
  '(ex.: "Parque Nacional de Sete Cidades", "Serra da Capivara", "Delta do Parnaíba", "BR-343"), sem traduzir.',
].join('\n');

// Orientações de contingência, usadas se o Gemini falhar
const contingencia = {
  pt: { chuva_forte: 'Chuva forte provável: troque passeios ao ar livre por atrações cobertas e evite trilhas.', chuva: 'Possibilidade de chuva: leve capa ou guarda-chuva e tenha um plano B coberto.', calor_extremo: 'Calor extremo: evite o sol entre 10h e 16h, hidrate-se e use protetor solar.', calor: 'Dia quente: prefira passeios cedo ou ao fim da tarde e beba água com frequência.', frio: 'Noites frias: leve agasalho para o início da manhã e a noite.', ok: 'Tempo favorável: aproveite os passeios ao ar livre com protetor solar.' },
  en: { chuva_forte: 'Heavy rain likely: swap outdoor visits for indoor attractions and avoid trails.', chuva: 'Chance of rain: bring a raincoat or umbrella and keep an indoor plan B.', calor_extremo: 'Extreme heat: avoid the sun from 10 am to 4 pm, stay hydrated and wear sunscreen.', calor: 'Hot day: go out early or late in the afternoon and drink water often.', frio: 'Cold nights: bring a jacket for early mornings and evenings.', ok: 'Good weather: enjoy outdoor visits and wear sunscreen.' },
  es: { chuva_forte: 'Lluvia fuerte probable: cambie los paseos al aire libre por atracciones cubiertas y evite senderos.', chuva: 'Posibilidad de lluvia: lleve impermeable o paraguas y tenga un plan B cubierto.', calor_extremo: 'Calor extremo: evite el sol entre las 10 y las 16 h, hidrátese y use protector solar.', calor: 'Día caluroso: salga temprano o al final de la tarde y beba agua con frecuencia.', frio: 'Noches frías: lleve abrigo para la mañana temprano y la noche.', ok: 'Buen tiempo: disfrute de los paseos al aire libre con protector solar.' },
};
const textosContingencia = contingencia[entrada.idioma] ?? contingencia.en;
const orientacoesContingencia = (alertas.length ? alertas : ['ok']).map((a) => `• ${textosContingencia[a]}`).join('\n');

return [{ json: { ...entrada, nivel, alertas, previsao, prompt, orientacoes_contingencia: orientacoesContingencia } }];

const avaliacao = $('Avaliar Chuva e Temperatura').first().json;
const resposta = $input.first().json ?? {};
const texto = (resposta.candidates?.[0]?.content?.parts ?? [])
  .map((p) => p.text ?? '').join('').replace(/[*#`_]/g, '').trim();
const usouGemini = texto.length > 0;

return [{
  json: {
    destino: avaliacao.destino,
    idioma: avaliacao.idioma,
    nivel: avaliacao.nivel,
    alertas: avaliacao.alertas,
    previsao: avaliacao.previsao,
    orientacoes: usouGemini ? texto : avaliacao.orientacoes_contingencia,
    fonte_orientacoes: usouGemini ? 'gemini' : 'contingencia',
    gerado_em: new Date().toISOString(),
  },
}];
